#include <iostream>
#include <string>
using namespace std;

struct Drone {
    int id;
    string name;
    int battery;
    int altitude;
};

bool is_launch_ready(const Drone &d) {
    return d.battery >= 50 && d.altitude >= 0;
}

int main() {
    int id, bat, alt;
    string name;
    cin >> id >> name >> bat >> alt;

    Drone d = {id, name, bat, alt};
    bool ready = is_launch_ready(d);
    cout << "LAUNCH READY: " << (ready ? 1 : 0) << endl;
    return 0;
}

