#include <iostream>
#include <cmath>
using namespace std;

int main() {
    int battery, n;
    cin >> battery >> n;

    int cur_x = 0, cur_y = 0;
    for (int i = 0; i < n; i++) {
        int x, y;
        cin >> x >> y;
        int dist = abs(x - cur_x) + abs(y - cur_y);
        battery -= dist;
        if (battery < 0) {
            battery = 0;
        }
        cur_x = x;
        cur_y = y;
    }

    cout << "FINAL BATTERY: " << battery << endl;
    return 0;
}

